import assert from 'node:assert/strict';
import {createTransferWorkspace, createProgressFeed, collectProgressTelemetry} from './src/workspace.js';
const deferred = () => { let resolve; const promise = new Promise(r => resolve = r); return {promise, resolve}; };
const old = deferred();
const history = [], shown = [], queues = [], notices = [], cancelled = [];
let detaches = 0;
const feed = createProgressFeed({initialPacket: 'warm', decode: p => p === 'old' ? old.promise : p, onDetach: () => detaches++});
const workspace = createTransferWorkspace({transport: () => {}, onCancel: x => cancelled.push(x.attemptId), record: x => queues.push(x), showQueued: x => notices.push(x), recordProgress: x => history.push(x.frame), showProgress: x => shown.push(x.frame)});
const file = {id: 'a', progressFeed: feed};
workspace.select(file);
assert.deepEqual(history, ['warm']);
assert.deepEqual(shown, ['warm']);
feed.emit('old'); feed.emit('new'); old.resolve('old decoded');
await Promise.resolve();
assert.deepEqual(history, ['warm', 'new', 'old decoded']);
assert.deepEqual(shown, ['warm', 'new']);
workspace.hide();
assert.equal(detaches, 1);
workspace.select(file);
assert.deepEqual(shown, ['warm', 'new', 'warm']);
workspace.retry();
assert.equal(detaches, 3);
assert.deepEqual(queues.map(x => x.kind), ['select', 'select', 'retry']);
assert.equal(notices.length, 3);
workspace.dispose();
assert.equal(detaches, 4);
assert.deepEqual(cancelled, [1,2,3]);
const deltas = [];
const stop = collectProgressTelemetry(feed, x => deltas.push(x));
assert.deepEqual(deltas, []);
feed.emit('delta'); stop();
assert.deepEqual(deltas, ['delta']);
let reentrantWorkspace, reentrantDetach = 0;
const reentrantFeed = createProgressFeed({initialPacket: 'warm', onDetach: () => reentrantDetach++});
reentrantWorkspace = createTransferWorkspace({transport: () => {}, onCancel: () => {}, record: () => {}, showQueued: () => {}, recordProgress: () => reentrantWorkspace.hide(), showProgress: () => {throw Error('stale display');}});
reentrantWorkspace.select({id:'b',progressFeed:reentrantFeed});
assert.equal(reentrantDetach, 1);
assert.equal(reentrantWorkspace.snapshot().visitId, null);
console.log('progress integration checks passed');
EOF"

