 2	export function watchTransferProgress(feed, receive, record) {
 3	  let nextFrame = 0;
 4	  let displayedFrame = 0;
 5	  const listener = event => {
 6	    const frameNumber = ++nextFrame;
 7	    const deliver = frame => {
 8	      record(frame);
 9	      if (frameNumber > displayedFrame) {
10	        displayedFrame = frameNumber;
11	        receive(frame);
12	      }
13	    };
14	    const decoded = feed.decode(event.detail);
15	    if (decoded && typeof decoded.then === "function") decoded.then(deliver);
16	    else deliver(decoded);
17	  };
18	  feed.target.addEventListener("progress", listener);
19	  feed.start();
20	  return () => feed.target.removeEventListener("progress", listener);
21	}

